"""Rebuild the offline guide after editing Markdown documentation. Requires markdown."""
from pathlib import Path
import html
import json
import re
import markdown

ROOT = Path(__file__).resolve().parents[1]
documents = [ROOT / 'README.md'] + sorted((ROOT / 'docs').rglob('*.md'))
ids = {p.resolve(): 'doc-' + str(i) for i, p in enumerate(documents)}
chapters = []
for p in documents:
    content = markdown.markdown(p.read_text(encoding='utf-8'), extensions=['tables', 'fenced_code', 'sane_lists'])
    def link(match):
        target = match.group(1)
        resolved = (p.parent / target.split('#')[0]).resolve()
        return 'href="#' + ids[resolved] + '"' if resolved in ids else match.group(0)
    content = re.sub(r'href="([^"]+)"', link, content)
    chapters.append(f'<details class="document" id="{ids[p.resolve()]}"><summary>{html.escape(str(p.relative_to(ROOT)))}</summary><article>{content}</article></details>')

page = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Campus Parcel System · Visual field guide</title>
<style>
:root{--paper:#f5f3eb;--ink:#182f2b;--muted:#53645e;--line:#cbd2c6;--green:#246947;--lime:#d8ee96;--orange:#ffd7ac}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:85px}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.6 system-ui,sans-serif}header{position:sticky;top:0;z-index:5;background:var(--paper);border-bottom:1px solid var(--line);padding:15px 4vw;display:flex;justify-content:space-between;align-items:center;gap:20px}header strong{font-size:14px;letter-spacing:.08em}nav{display:flex;gap:22px;flex-wrap:wrap}a{color:inherit;text-underline-offset:5px}nav a{font-size:13px;text-decoration:none}main{max-width:1200px;margin:auto;padding:0 32px}section{padding:70px 0;border-bottom:1px solid var(--line)}.eyebrow{font:12px ui-monospace,monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--green)}h1{font:clamp(48px,7vw,88px)/1.04 Georgia,serif;letter-spacing:-.045em;margin:20px 0 26px;max-width:830px}h2{font:clamp(32px,4vw,48px)/1.13 Georgia,serif;margin:12px 0 24px;letter-spacing:-.025em}h3{font-size:20px;margin:14px 0}.intro{font-size:21px;max-width:700px;color:var(--muted)}.hero{display:grid;grid-template-columns:1.5fr .65fr;gap:50px;align-items:center}.stamp{border:1px solid var(--green);padding:28px;transform:rotate(2deg);background:var(--lime)}.stamp b{font:70px/1 Georgia,serif;display:block}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.panel{border:1px solid var(--line);padding:26px;background:#fffcf5}.panel p{color:var(--muted)}.num{font:40px Georgia,serif;color:var(--green)}.lab{background:var(--ink);color:#f5f3eb;padding:32px;border-radius:4px;margin:24px 0}.lab p{color:#c6d4c8}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0 0}button,input,select{font:inherit}button{cursor:pointer;border:1px solid var(--green);background:var(--green);color:white;padding:10px 19px;border-radius:4px}button.secondary{background:transparent;color:inherit;border-color:currentColor}button:disabled{opacity:.45;cursor:default}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid #b86a13;outline-offset:4px}.nodes{display:flex;align-items:center;gap:12px;flex-wrap:wrap;min-height:85px}.node{display:inline-flex;align-items:center;justify-content:center;min-width:86px;padding:16px;background:var(--lime);color:var(--ink);border:1px solid #9ab166;animation:arrive .45s ease}.arrow{font-size:25px}.label{font:12px ui-monospace,monospace;text-transform:uppercase;letter-spacing:.1em;color:inherit;opacity:.75;margin-top:22px}.step-title{font-size:25px;font-weight:650;margin:8px 0}.status-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.status{border-top:2px solid #789286;padding-top:15px}.status b{display:block;font-size:18px;color:var(--lime)}.timeline{display:flex;gap:7px;margin:0 0 25px}.timeline span{height:5px;flex:1;background:#567065}.timeline span.on{background:var(--lime)}.split{display:grid;grid-template-columns:1fr 1fr;gap:32px}.note{padding:18px 22px;border-left:4px solid var(--green);background:#e7ebdf}.ring{display:flex;justify-content:center;gap:15px;flex-wrap:wrap;padding:25px 0}.resource{padding:22px;border:1px solid #789286;min-width:110px;text-align:center}.resource.active{background:var(--lime);color:var(--ink);transform:translateY(-8px);transition:transform .3s}.resource small{display:block}.answer{margin-top:20px;padding:20px;background:#e7ebdf;min-height:100px}.questions{display:flex;gap:9px;flex-wrap:wrap}details{border-bottom:1px solid var(--line);padding:16px 0}summary{cursor:pointer;font-weight:650}article{padding:12px 8px;overflow-wrap:anywhere}article h1{font-size:38px}article h2{font-size:29px}article h3{font-size:22px}table{border-collapse:collapse;width:100%;font-size:14px;display:block;overflow-x:auto}td,th{text-align:left;border:1px solid var(--line);padding:10px}pre{padding:20px;background:#e9e9df;overflow:auto;font-size:14px}code{font-family:ui-monospace,monospace;font-size:.87em}input{width:100%;padding:14px;border:1px solid var(--line);background:white;margin:15px 0}.doc-count{font-size:14px;color:var(--muted)}footer{padding:35px 0;color:var(--muted);font-size:14px}.hidden{display:none}@keyframes arrive{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}@media(max-width:750px){main{padding:0 20px}header{position:relative;align-items:flex-start;flex-direction:column;gap:10px}nav{gap:14px}.hero,.grid,.split,.status-grid{grid-template-columns:1fr}.stamp{max-width:260px}.hero{gap:20px}section{padding:45px 0}.lab{padding:22px}h1{font-size:52px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}}@media print{header,.controls,.questions,input{display:none}.lab{background:white;color:black}.lab p,.status b{color:black}details article{display:block}section{break-inside:avoid}body{font-size:12px}}
</style></head><body>
<header><strong>CAMPUS / FIELD GUIDE</strong><nav aria-label="Sections"><a href="#overview">Overview</a><a href="#journey">Walkthrough</a><a href="#structures">Structures</a><a href="#exceptions">What if?</a><a href="#present">Present</a><a href="#library">All docs</a></nav></header>
<main><section id="overview" class="hero"><div><div class="eyebrow">DSTR assignment · Tasks 1–3</div><h1>A parcel arrives.<br>What happens next?</h1><p class="intro">Follow one parcel from registration to collection. See how three linked structures keep the record, choose the work, and share the resources.</p><a href="#journey">Start the interactive walkthrough →</a></div><aside class="stamp"><div class="eyebrow">One integrated system</div><b>3</b><p>members<br>three responsibilities<br>one parcel journey</p></aside></section>
<section><div class="eyebrow">01 / Understand the assignment</div><h2>Manage the campus parcel desk.</h2><p class="intro">Staff need to know what arrived, which service happens next, and who or which counter will handle it. Your program models that work in a C++ console.</p><div class="grid"><div class="panel"><span class="num">01</span><h3>Receive & retain</h3><p>Register, find, edit and route parcels. A singly linked list stores full records; a FIFO queue stores waiting parcel IDs.</p><code>task1.cpp · Member 1 / your part</code></div><div class="panel"><span class="num">02</span><h3>Organize the work</h3><p>Create service requests, recommend urgent work first, then process, complete, cancel or interrupt the request.</p><code>task2.cpp · Member 2</code></div><div class="panel"><span class="num">03</span><h3>Share resources</h3><p>Manage counters and delivery personnel. A circular list rotates allocation among available resources of the correct type.</p><code>task3.cpp · Member 3</code></div></div><p class="note">For this three-member project, Tasks 1–3 are the required responsibilities described in the existing project documentation. Tasks 4–5 are excluded. Service outcome rules below are team implementation choices. This guide consolidates the repository documentation; check the original assignment PDF for its exact wording and marking rubric.</p></section>
<section id="journey"><div class="eyebrow">02 / Watch the whole flow</div><h2>One parcel. Three modules working together.</h2><p>Mock parcel: <b>P1</b> · Aina · recipient <b>S1001</b> · tracking <b>TRK001</b>. Use Next or Play to trace a collection. This is a teaching simulation of the C++ behavior.</p><div class="lab"><div id="progress" class="timeline" aria-hidden="true"></div><div id="walk" aria-live="polite"></div><div class="controls"><button id="back" class="secondary">← Back</button><button id="next">Next step →</button><button id="play" class="secondary">Play</button><button id="reset" class="secondary">Reset</button></div></div><div class="note">Remember: the record remains in the parcel list after intake processing. Only its waiting ID leaves the queue. Completing collection updates P1 and R1 and makes C1 available again.</div></section>
<section id="structures"><div class="eyebrow">03 / Open the data structures</div><h2>Different structures answer different questions.</h2><div class="split"><div><h3>Task 1 · Where is my parcel?</h3><p>The record list owns the full data. Head insertion displays the newest parcel first. Intake keeps only IDs and processes the oldest arrival first.</p><div class="lab"><div class="label">Full records · newest first</div><div id="records" class="nodes"></div><div class="label">Waiting IDs · front → rear</div><div id="queue" class="nodes"></div><p id="queue-note" aria-live="polite"></p><div class="controls"><button id="enqueue">Register parcel</button><button id="dequeue" class="secondary">Route front</button><button id="queue-reset" class="secondary">Reset</button></div></div><p><b>Pointer rule:</b> removing the only queue node sets both front and rear to nullptr. Save the next pointer before deleting a node.</p></div><div><h3>Task 2 · Which request goes next?</h3><p>Sorted linked insertion places Urgent before Normal. Equal-priority requests keep creation order. Click to reveal the insertion trace.</p><div class="lab"><div id="priority" class="nodes"></div><p id="priority-note" aria-live="polite"></p><div class="controls"><button id="insert">Insert next request</button><button id="priority-reset" class="secondary">Reset</button></div></div><p><b>Order:</b> Normal A, Urgent B, Normal C, Urgent D becomes B → D → A → C. The first Pending request is recommended; staff can choose another ID.</p></div></div><h3>Task 3 · Who handles it?</h3><p>C1 and C2 are counters. D1 is delivery personnel. Allocate then release one request at a time below to see separate round-robin cursors. The real application skips Occupied and Unavailable resources.</p><div class="lab"><div class="ring" id="ring"><div class="resource" data-id="C1">C1<small>Counter</small></div><div class="resource" data-id="C2">C2<small>Counter</small></div><div class="resource" data-id="D1">D1<small>Delivery</small></div></div><p id="ring-note" aria-live="polite">A circular list links the last node back to the first. Counters and delivery personnel each remember their own next position.</p><div class="controls"><button id="counter">Allocate counter</button><button id="driver">Allocate delivery</button><button id="ring-reset" class="secondary">Reset</button></div></div><div class="grid"><p><b>List lookup O(P)</b><br>Walk through parcel nodes until the ID matches. P means stored parcels.</p><p><b>Priority insertion O(R)</b><br>Find the sorted position. Retained terminal requests count toward R.</p><p><b>Resource selection O(S)</b><br>Scan at most one circular cycle. S means resources.</p></div><p class="note">Queue enqueue, dequeue and peek are O(1). Whole registration is O(P) because it checks duplicates. Linked structures grow dynamically; arbitrary searching still takes traversal.</p></section>
<section id="exceptions"><div class="eyebrow">04 / Validate before changing state</div><h2>What if something goes wrong?</h2><p>Pick a case. Explain what the program should reject and what stays consistent.</p><div class="questions" id="cases"></div><div class="answer" id="case-answer" aria-live="polite"></div><h3>Service outcomes at a glance</h3><table><thead><tr><th>Service</th><th>Resource</th><th>Successful parcel outcome</th></tr></thead><tbody><tr><td>Collection</td><td>Counter</td><td>Collected</td></tr><tr><td>CampusDelivery / Redelivery</td><td>Delivery personnel</td><td>Delivered</td></tr><tr><td>SpecialHandling</td><td>Delivery personnel</td><td>OnHold, ready for a staff decision</td></tr><tr><td>ReturnToSender</td><td>Delivery personnel</td><td>Returned</td></tr></tbody></table><p>An explicit Returned outcome also returns a valid in-progress service. Collected, Delivered, Returned and Cancelled parcels are terminal. Missing must first recover to OnHold before resuming.</p></section>
<section id="present"><div class="eyebrow">05 / Your five-minute presentation</div><h2>Explain the reason. Show the behavior.</h2><div class="split"><div><ol><li><b>0:00–0:45 · Purpose.</b> “My part receives parcels, keeps their records and preserves arrival order.”</li><li><b>0:45–1:45 · Register two parcels.</b> Use TRK001 / S1001 and TRK002 / S1002 with complete recipient details. Show newest-first records versus FIFO intake. Try duplicate tracking.</li><li><b>1:45–2:45 · Route P1.</b> Choose Collection. Show R1 and search P1 again: the record still exists.</li><li><b>2:45–3:45 · Pointers.</b> Open IntakeQueue::enqueue/dequeue. Explain front, rear and the last-node case.</li><li><b>3:45–5:00 · Reasoning.</b> Explain O(P) search, empty intake and OnHold recovery. State that data disappears on exit.</li></ol></div><div class="panel"><h3>Open code in this order</h3><p><code>include/models.hpp</code><br>What a Parcel contains.</p><p><code>include/task1.hpp</code><br>Records, queue and module ownership.</p><p><code>src/task1.cpp</code><br>registerParcel → enqueue/dequeue → processNext.</p><p><code>src/task2.cpp</code><br>createRequest is the handoff: it updates the parcel and removes its waiting ID.</p><a href="#library">Expand the rehearsal guide for exact locations and questions ↓</a></div></div><details><summary>Quick oral questions — reveal suggested answers</summary><p><b>Why both structures?</b> The record must remain searchable after intake ends. The queue only represents waiting order.</p><p><b>Why store IDs?</b> One parcel record remains the source of truth instead of several changing copies.</p><p><b>Why validate before releasing?</b> A wrong recipient or invalid completion must not free an occupied resource while work is still active.</p><p><b>Why a destructor?</b> Every manually allocated node must be freed. Owning structures disable copying to prevent shallow copies and double deletion.</p><p><b>Why separate cursors?</b> Alternating delivery and counter allocations should not reset the other resource type’s rotation.</p></details><h3>Build and run on Linux</h3><pre><code>mkdir -p build
g++ -std=c++17 -Wall -Wextra -Wpedantic -Werror -I include src/main.cpp src/task1.cpp src/task2.cpp src/task3.cpp -o build/parcel_system
./build/parcel_system</code></pre><p>Run from the project folder. Recompile after changing C++. The existing review recorded 543 C++ checks and 28 console scenarios passing; those results cover the tested workflows, not every possible input.</p></section>
<section id="library"><div class="eyebrow">06 / Complete reference library</div><h2>Every document, in the same file.</h2><p>Use the visual sections first. Expand the original guides when you need exact code explanations, test details or presentation answers. Search filters whole documents by their text.</p><label for="search">Find a topic or file</label><input id="search" type="search" placeholder="Try: nullptr, cancellation, task1, complexity…"><div id="doc-count" class="doc-count" aria-live="polite"></div><div id="documents">__DOCUMENTS__</div></section><footer>Smart Campus Parcel System · Offline visual guide · Rebuild with docs/build_visual_guide.py after documentation changes. No network or external assets required.</footer></main>
<script>
const steps=[
['Before arrival','No records yet. Staff will enter the parcel and register counter C1.','Not registered','No request','C1 · Available','Task 1: validate required fields and unique tracking before saving.'],
['Register P1','Aina’s parcel gets an ID and arrival time. The record list stores its complete details; intake gets only P1.','Received','No request','C1 · Available','Records: P1 → nullptr | Intake: front P1 rear.'],
['Route for collection','Process the oldest waiting parcel. Task 2 creates R1 and removes P1 from intake.','AwaitingCollection','R1 · Pending','C1 · Available','P1 stays in the record list. There is at most one active request for it.'],
['Assign a counter','Task 3 selects an available counter. Both the request and resource store each other’s IDs.','AwaitingCollection','R1 · Assigned → C1','C1 · Occupied → R1','The resource must match the service type: collection uses a counter.'],
['Start the service','Staff process the assigned request. The resource remains occupied.','AwaitingCollection','R1 · InProgress','C1 · Occupied → R1','An unassigned Pending request cannot start processing.'],
['Verify and complete','Enter S1001 and nonblank outcome details. Validate all links, then release C1 and update both statuses.','Collected','R1 · Completed','C1 · Available','Assignment IDs are cleared. P1 is terminal; R1 remains searchable until explicitly removed.']];
let step=0,timer=null;const $=id=>document.getElementById(id);
function draw(){const s=steps[step];$('progress').innerHTML=steps.map((_,i)=>'<span class="'+(i<=step?'on':'')+'"></span>').join('');$('walk').innerHTML='<div class="eyebrow">Step '+(step+1)+' / '+steps.length+'</div><div class="step-title">'+s[0]+'</div><p>'+s[1]+'</p><div class="status-grid">'+['Parcel P1','Request R1','Resource C1'].map((l,i)=>'<div class="status"><small>'+l+'</small><b>'+s[i+2]+'</b></div>').join('')+'</div><p>'+s[5]+'</p>';$('back').disabled=step===0;$('next').disabled=step===steps.length-1;}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Play';}
$('next').onclick=()=>{stop();step=Math.min(step+1,5);draw()};$('back').onclick=()=>{stop();step=Math.max(step-1,0);draw()};$('reset').onclick=()=>{stop();step=0;draw()};$('play').onclick=()=>{if(timer){stop();return}if(step===5)step=0;draw();$('play').textContent='Pause';timer=setInterval(()=>{step++;draw();if(step===5)stop()},3500)};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
function nodes(ids){return ids.length?ids.map(id=>'<span class="node">'+id+'</span>').join('<span class="arrow" aria-hidden="true">→</span>')+'<span class="arrow">→ ∅</span>':'<span>Empty · nullptr</span>'}
let records=[],queue=[],serial=0;
function drawQueue(note){$('records').innerHTML=nodes(records);$('queue').innerHTML=nodes(queue);$('queue-note').textContent=note;$('dequeue').disabled=!queue.length;}
$('enqueue').onclick=()=>{const id='P'+(++serial);records.unshift(id);queue.push(id);drawQueue(id+' stored at record head and appended at intake rear.')};$('dequeue').onclick=()=>{const id=queue.shift();drawQueue(id+' leaves intake; its record remains.'+(!queue.length?' front = rear = nullptr.':''))};$('queue-reset').onclick=()=>{records=[];queue=[];serial=0;drawQueue('Register two parcels, then route the front ID.')};
const incoming=[['A',1],['B',0],['C',1],['D',0]];let pending=[],inserted=0;
function drawPriority(){ $('priority').innerHTML=nodes(pending.map(x=>x[0]+' · '+(x[1]?'Normal':'Urgent')));$('insert').disabled=inserted===4;}
$('insert').onclick=()=>{const item=incoming[inserted++];pending.push(item);pending.sort((a,b)=>a[1]-b[1]||incoming.indexOf(a)-incoming.indexOf(b));drawPriority();$('priority-note').textContent=item[0]+' inserted. Earlier creation wins ties within the same priority.'};$('priority-reset').onclick=()=>{pending=[];inserted=0;drawPriority();$('priority-note').textContent='Insert A, B, C and D one at a time.'};
let cursor=0;function allocate(type){const id=type==='counter'?['C1','C2'][cursor++%2]:'D1';document.querySelectorAll('.resource').forEach(el=>el.classList.toggle('active',el.dataset.id===id));$('ring-note').textContent=id+' selected and released in this example. '+(type==='counter'?'Next counter: '+['C1','C2'][cursor%2]+'. Delivery cursor is unchanged.':'Next delivery: D1 (the only driver). Counter cursor is unchanged.');}
$('counter').onclick=()=>allocate('counter');$('driver').onclick=()=>allocate('driver');$('ring-reset').onclick=()=>{cursor=0;document.querySelectorAll('.resource').forEach(el=>el.classList.remove('active'));$('ring-note').textContent='Reset. Next counter C1; next delivery D1.'};
const cases=[['Duplicate tracking','Reject registration. The new parcel and waiting ID are not inserted. Tracking uniqueness is checked with one scan; comparisons are case-sensitive.'],['Wrong recipient','Reject completion before release. The parcel stays AwaitingCollection, R1 stays InProgress and C1 stays Occupied.'],['No available resource','Assignment fails. The request remains Pending with no resource. No occupied resource is stolen.'],['Empty intake','Report no waiting parcel. Do not dereference a null front pointer.'],['Missing parcel','For active work, interrupt via Task 2: request becomes Cancelled, resource is released, parcel becomes Missing. Recover to OnHold before resuming a new service.'],['Cancel vs interrupt','Full cancellation makes the parcel terminal Cancelled. Interruption closes the current request but leaves Missing/OnHold so recovery is possible.'],['Release manually','An Assigned/InProgress request returns to Pending. Both assignment IDs clear and the resource becomes Available. Original priority and sequence remain.'],['Edit during service','Reject edits while an active request exists: changing recipient or destination could contradict that request. Terminal parcels cannot be edited either.'],['Remove a parcel','Require Cancelled and no active request. Remove any waiting membership before deleting its record node.'],['Last queue node','After removal, front and rear must both be nullptr. Leaving rear pointing to deleted memory would break a later enqueue.'],['Delivered redelivery','Reject. Delivered is terminal. Redelivery is another attempt on an unfinished parcel, after interruption and recovery as needed.'],['Exit and restart','All data is in memory and disappears. Parcel/request numbering restarts. There is no file or database persistence.']];
$('cases').innerHTML=cases.map((c,i)=>'<button class="secondary" data-case="'+i+'">'+c[0]+'</button>').join('');function choose(i){$('case-answer').textContent=cases[i][1];document.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.case)===i)))};$('cases').onclick=e=>{if(e.target.dataset.case!==undefined)choose(Number(e.target.dataset.case))};
const docs=[...document.querySelectorAll('.document')];$('search').oninput=()=>{const q=$('search').value.toLowerCase().trim();let count=0;docs.forEach(d=>{const show=d.textContent.toLowerCase().includes(q);d.hidden=!show;if(show)count++});$('doc-count').textContent=count+' of '+docs.length+' documents'};
function openHash(){const el=document.getElementById(location.hash.slice(1));if(el&&el.tagName==='DETAILS'){el.hidden=false;el.open=true;el.scrollIntoView()}}window.addEventListener('hashchange',openHash);draw();drawQueue('Register two parcels, then route the front ID.');drawPriority();$('priority-note').textContent='Insert A, B, C and D one at a time.';choose(0);$('search').oninput();openHash();
</script></body></html>'''
output = ROOT / 'docs' / 'VISUAL_GUIDE.html'
output.write_text(page.replace('__DOCUMENTS__', '\n'.join(chapters)), encoding='utf-8')
print(f'Built {output.name}: {len(documents)} embedded documents, {output.stat().st_size:,} bytes')
